-- Inventario: simulado, de 0 a 199 unidades de cada producto en cada sucursal.
-- setseed y el ORDER BY hacen que las cantidades sean las mismas en cada ejecución.
SELECT setseed(0.42);
SELECT id_producto, id_sucursal, floor(random() * 200)::int
FROM (SELECT p.id_producto, s.id_sucursal FROM producto p CROSS JOIN sucursal s ORDER BY 1, 2) AS pares;

COMMIT;
